INSERT INTO `article` VALUES (1154, '《凌云诺》手游主题曲《凌云赋》', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/234632d0d5b1534bd8ab250deeaaf216.jpg', '动漫,新歌,轻音乐,DJ', '作为友谊时光强推的年度大型女性古风手游《凌云诺》的主题曲，歌曲中融入了戏腔、rap、古风元素，为听众和玩家带来不一样的古风音乐表现方式，将游戏中女性自强，报效国家，创盛世太平的积极精神传达给大家。', '凌云诺手游', 0, '正常', '蓝光', '2022-03-13 23:06:12');
INSERT INTO `article` VALUES (1155, '《知否、知否》电视剧（知否、知否，应是绿肥红瘦）主题曲MV', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/c91c3f7356649ad7c9b56ee89d383cb6.jpg', '拉丁', '这部剧当时也是火遍大江南北  留下美好的记忆', '九墨音乐', 0, '正常', '超清', '2022-03-13 23:06:12');
INSERT INTO `article` VALUES (1156, '【诺言Jason】孤勇者', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/08ce61f9b10c1e75546715e3ef4e38cd.jpg', '治愈,治愈', '不完美的梦，可以不乘风。\n一腔孤勇者，奔赴一个梦。\n从黑暗中生长的信念会成为光，\n与命运对峙过的人，都是勇敢者。\n\n作词：唐恬\n作曲：钱雷\n原唱：陈奕迅\n翻唱/混音：诺言Jason\n剪辑：银灯', '诺言Jason', 0, '正常', '蓝光', '2022-03-13 23:06:12');
INSERT INTO `article` VALUES (1157, '仙剑奇侠七传预告片_Mux缩小小', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/8aa864292b957cc73da6b7d7a8b83af3.jpg', '摇滚,酒吧', '暂无简介', '可乐加冰块啦啦', 0, '正常', '流畅', '2022-03-13 23:06:12');
INSERT INTO `article` VALUES (1158, '《有生之年》愿你历尽千帆归来仍是少年', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/07ca6f2b788f67dd420b9b0d49698fa9.jpg', '粤语', '人生最幸福的四件事：有人信你，有人爱你，有人帮你，有人懂你。谨以此歌，献给我的朋友——安吉祥，感谢这一路有你陪伴，让我拥有了一段被信任，被爱，被扶持，被懂得的人生，幸甚有你。愿你所爱之人即是爱你之人，愿你活得简单自在，愿你历尽千帆，归来仍是少年，愿你前途坦荡，再无风霜。\n\n原唱：张远\n翻唱：花千涵\n作词：周号铭\n作曲：周号铭\n编曲：韩冰\n后期：花千涵\nPV：阿茂吃茂茂', '花千涵_文柒兩', 0, '正常', '高清', '2022-03-13 23:06:12');
INSERT INTO `article` VALUES (1159, '躲过人群，沉入海底|克莱因蓝|后半段人声耳机食用', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/ddd9ff0d754e9ec295194302726cb7db.jpg', '日本,粤语,古风', '后半段的念白是我回忆中很多抑郁症患者会说的话，我全都录出来分声道剪了进去。\n希望你身边的朋友向你说这些话的时候，你不会以为这是无病呻吟。\n或许你们伸出的手，就是他们最后的救命稻草。\n也希望所有人都学会追求光明，不要沉入海底。\n\n原唱：一支榴莲\n作曲 : PSROSIE\n作词 : PSROSIE\n翻唱|后期|视频：云扶\n封面字素：不云\n字幕字素：四两夏肉肉', '云扶', 0, '正常', '超清', '2022-03-13 23:06:12');
INSERT INTO `article` VALUES (1160, '《画离弦》MV——九墨', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/b72438bd0af416158d557c20cb73e64c.png', '游戏,怀旧', '辛苦制作古风《画离弦》，希望能打动您的耳膜~ 同步上传抖音~抖音号：345931688', '九墨音乐', 0, '正常', '超清', '2022-03-13 23:06:12');
INSERT INTO `article` VALUES (1161, '【忘月幽x司音】繁华唱遍（姐妹版）', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/2d564bd456c531e211ec099536f33699.png', '摇滚,拉丁,金曲,网络红歌,运动', '繁华唱遍\n\n我以为那个时代已过去，殊不知当你歌唱时，属于那个时代的一切都在归来。\n——题记\n\n作曲：papaw泡泡\n编曲：papaw泡泡\n作词：Vagary\n原唱：乐正绫\n调 教：纳兰寻风\n\n翻唱：忘月幽&司音\n混音：奶妈月\n题字：洛年\n美工：正正\npv压制：时桑', '司音*', 0, '正常', '蓝光', '2022-03-13 23:06:12');
INSERT INTO `article` VALUES (1162, '原创作品《寄居》赤身而来 并不孤单', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/6519c3b7aa45769e6f7d364a3e784836.jpg', '动漫,影视', '《琳大侠Live Show》NO.128 原创作品《寄居》赤身而来 并不孤单\n没有更新的11月，珍波椰乐队其实一直也没有闲下来，历经了一个多月不断修改，我们的原创曲目《寄居》终于在12月和大家见面了。\n这次歌曲创作以成长为主题，讲述了寄居蟹从赤裸出生到成长途中找到属于自己的外壳与同伴，不断成长与蜕变的过程。也正如人类一样，当我们不断朝着目标努力向前，历经一次次的成长与蜕变，你希望能看见怎样的未来？\n希望你能在这首歌中找到答案！\n节目不出意外每周在各大视频平台同步更新~欢迎大家关注即使断更但依旧想给大家更多惊喜的琳大侠！', '琳大侠', 0, '正常', '蓝光', '2022-03-13 23:06:13');
INSERT INTO `article` VALUES (1163, '[幸福账单]石头《冬奥有我》', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/55e1e69f9fec1a9f1ef885aa552b9eb3.jpg', '新歌,治愈,国风,英文,DJ', '暂无简介', '歌手石头MUSIC', 0, '正常', '超清', '2022-03-13 23:06:13');
INSERT INTO `article` VALUES (1164, '【诺言Jason】不过光阴', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/1060639361fbdace316f98550e1e0d83.jpg', '国风,怀旧,拉丁', '白玉不毁寄初心\n尘埃落尽化云泥\n为仁由己任非议\n浮沉从不过光阴\n\n原著：《当年万里觅封侯》漫漫何其多 \n策划：洢晴 \n作编曲：淳毓\n作词：桃缘溪行 \n演唱/混音/和声：诺言Jason \n和声编写：千漓cc \n出品：千音绪音乐工作室/千小莺 \n曲绘：红茶\npv：祇沙Kouhiizerii', '诺言Jason', 0, '正常', '蓝光', '2022-03-13 23:06:13');
INSERT INTO `article` VALUES (1165, '【冥月】得过且过的勇者（原创PV付）', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/39b0361a58eb35f0f4da8647cc8f7b6b.jpg', '华语,游戏', '词曲：ilem‬\n翻唱：冥月\n后期：啊鲤\nPV/曲绘： 芯巴\n时之歌要素注意！！！', '冥月の翼', 0, '正常', '蓝光', '2022-03-13 23:06:13');
INSERT INTO `article` VALUES (1166, '陶笛演奏罗大佑这首《童年》熟悉的旋律，勾起了多少人的童年回忆', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/2bdafcc74dd04d65f246ec2d7632bc49.jpg', '新歌,拉丁,金曲,电音', '暂无简介', '解亚飞糖糖音乐家陶笛', 0, '正常', '蓝光', '2022-03-13 23:06:13');
INSERT INTO `article` VALUES (1167, '国风电音神曲：一念娑婆（心然&amp;阿册）', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/ac408baa0f0dde51bd668008c9a5b8da.jpg', '游戏,金属,说唱,怀旧,拉丁', '新歌来啦！这首歌烫嘴难度十级，对我们而言是全新风格的挑战~在副歌部分里，阿册老师念的是往~生~咒，而我演绎的黑化女主则是完全倒过来念的，但考虑到正经的咒语倒着念不妥，为此这段是残杨老师杜撰自创的咒语，没有真实的作用！请放心食用~！(づ￣ 3￣)づ', '心然', 0, '正常', '蓝光', '2022-03-13 23:06:13');
INSERT INTO `article` VALUES (1168, '《孤勇者》女声翻唱|《英雄联盟：双城之战》虐泪向剪辑', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/8d7ae7c5f37b00e8ec22fef928bc827d.png', '拉丁,经典,华语,校园', '谁说站在光里的才算英雄。\n\n（字幕后期有点错误，因为字素提供作者没有提供后半段的素材，所以请大家见谅鸭！）\n\n作词：唐恬\n作曲|编曲：钱雷\n原唱：陈奕迅\n翻唱|后期|视频：云扶', '云扶', 0, '正常', '蓝光', '2022-03-13 23:06:13');
INSERT INTO `article` VALUES (1169, '《完美国际2》十五周年主题曲“共赴天地一程”', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/bf1ebb428769a171abd5223d78b5fe1d.jpg', '运动,情歌,怀旧', '光阴荏苒，岁月如梭，11月30日《完美国际2》即将迎来它的十五岁生日。值此之际，我们特别打造十五周年主题曲《共赴天地一程》，与完美大陆勇士一同细数携手走过的无数日夜。', '完美国际2', 0, '正常', '蓝光', '2022-03-13 23:06:13');
INSERT INTO `article` VALUES (1170, '【翻唱】半生少年', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/b7ec3d475c742dc32bd82cb5cc65de1d.jpg', '摇滚', 'emmm 能咋办呢 就。。。敷衍的重新拼了一个呗~', '納蘭落雪', 0, '正常', '蓝光', '2022-03-13 23:06:13');
INSERT INTO `article` VALUES (1171, '冷暖书——纪念所有女生之间的友谊', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/b6ea0bee2fdc3b1af843117ee2201e42.jpg', 'DJ', '——这世上总有那么一个人\n不随时间空间变化\n依然懂你\n闺阁旧人，契若金兰。\n数载尺素，水北天南。\n各自相夫教子，\n常候来时有约。\n她们的故事里不会人走茶凉\n因为那杯茶 那盏酒\n一直都在用心温着。', '大橘为重音乐', 0, '正常', '蓝光', '2022-03-14 22:28:23');
INSERT INTO `article` VALUES (1172, '晚夜微雨问海棠【温柔女声翻唱】', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/c3d85c937f8650c2c6e2c4925063586b.png', '情歌,新歌,日韩', '可爱的粉丝朋友们，我来兑现我的歌辣！\nPV官方已授权哦！\n\n《晚夜微雨问海棠》翻唱\n原著：肉包不吃肉《二哈和他的白猫师尊》\n作词：唐酱\n作曲：陈亦洺 李一桑\n编曲：Mzf小慕\n原唱：陈亦洺(墨燃) 喧笑lirz(楚晚宁)\n翻唱|后期：云扶', '云扶', 0, '正常', '超清', '2022-03-14 22:28:23');
INSERT INTO `article` VALUES (1173, '『Honomi翻唱团』Take Me Higher', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/63af76fe46db486a71e60b4e3006556a.png', '新歌,校园', '-ここはハートが目覚めて花咲いて-\n-リスペクトしあう場所-\n＊＊＊＊＊\n＊staff以简介为准\n策划：玲雪，茴缘\nPV：那月子，江筱落\n后期：流月\n美工：畅歌\n＊＊＊＊＊\n唱见：\n星宫莓：梦樱\n雾矢葵：鹿泽桐\n紫吹兰：熙扬\n神崎美月：茴缘\n一之濑枫：森暮\n藤堂尤里卡：秋墨\n有栖川乙女：林溪\n北大路樱：墨烟（特邀）\n＊＊＊＊＊\n本单请了初代的8位来唱，虽然官官想了很久都没想出该怎么表达成品的惊艳，但这单的美女们真的特别特别帅！！！\n听就完事了！！大家听歌愉快~！！', '秋墨墨Aki', 0, '正常', '蓝光', '2022-03-14 22:28:24');
INSERT INTO `article` VALUES (1174, '逐光记', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/2fee368b3759f65c2da4209ad5831304.jpg', '英文,运动,台湾', '暂无简介', '扇宝', 0, '正常', '蓝光', '2022-03-14 22:28:24');
INSERT INTO `article` VALUES (1175, '我有明堂风雪裁《将进酒》策舟同人歌', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/e2981275c50e413366cdf9bea3554aa2.jpg', 'DJ,日本,金曲,网络红歌', '我有明堂风雪裁——《将进酒》策舟同人歌\r\n演唱：策安-诺言Jason/兰舟-Babystop_山竹\r\n策划：檀卿卿\r\n作曲：李星月\r\n作词：闻刀客\r\n编曲：洛劫\r\n和声编写：李星月/巫汐\r\n和声演唱：巫汐\r\n修对：临溪\r\n分轨/人声混音：牧子Assyria\r\n歌名题字：聆泽Lains\r\nPV全词：檀卿卿\r\nPV底图：白鹿\r\n美工：竹名君\r\nPV：浔漪Hazy\r\n立绘：胖叽叽叽叽叽/山烟雅坠\r\n授权画师：哮天小狗狗/Kuzpao鱼泡/遥山时人/南风。/霜月', '诺言Jason', 0, '正常', '蓝光', '2022-03-14 22:28:24');
INSERT INTO `article` VALUES (1176, '子弥 - 喜雨', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/edb20b6229ad46a3b3830ee5529f057c.jpg', '情歌,校园', '暂无简介', '子弥MiFaFa', 0, '正常', '蓝光', '2022-03-14 22:28:24');
INSERT INTO `article` VALUES (1177, 'ベリーメリークリスマス', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/0138984770404589a0be4ccd5a9b5cca.jpg', '儿童', 'Song by Very Merry Christmas\nCover by 墨逸轩\nメリークリスマス！！！\n圣诞快乐！！！\n这次翻唱了 天月-あまつき- 的 ベリーメリークリスマス，趁着这次圣诞节再一次翻唱了一首有关圣诞的日语歌曲，希望各位喜欢。喜欢的别忘了XXX哟！', '墨逸轩_Asaitsunoki', 0, '正常', '超清', '2022-03-14 22:28:24');
INSERT INTO `article` VALUES (1178, '九域无疆', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/997a512414d750963eb2e1c4feb874da.jpg', '电音,旅行,网络红歌,电音', '《九域无疆》\r\n\r\n总策划/制作人：嫦綰、Coco烟岚\r\n作词：苏药卿、马小瞳、烟花瀑布、紫羽映月、良时、七手、上河、素昭、丝齐、紫云纱、安羽、野野、凉盏\r\n作曲：黄诗扶HBY\r\n演唱：小曲儿、HITA、司夏、Smile_小千、Braska、冥月、流浪的蛙蛙\r\n编曲：sea云\r\n和声：嫦绾、冥月、司夏\r\n混音：NamieMeng\r\n海报/pv底图：苍茕\r\n题字：聆泽\r\nPv：缄玫\r\n监策：紫羽映月、安羽\r\n监制：白衣SAMA、妖旋宝\r\n出品：步知名原创组\r\n\r\n', '步知名原创合唱组', 0, '正常', '标清', '2022-03-14 22:28:24');
INSERT INTO `article` VALUES (1179, '“不辞冰雪为卿热”', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/057e878a63e20ea4aa934a58c22f3cc0.png', '日韩', '《少年游之一寸相思》\n宝藏剧，很好看。\n\n《涉川》翻唱\n词：怀袖\n曲：少司命\n编曲：灰原穷/纪粹希\n和声：小时姑娘\n和声编写：银临\n原唱：不才\n翻唱：云扶', '云扶', 0, '正常', '超清', '2022-03-14 22:28:24');
INSERT INTO `article` VALUES (1180, '【诺言Jason】一生一次心一动(《斛珠夫人》电视剧主题曲', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/0df9297939aadfc28738c96043dc7cbf.jpg', '华语,国风,儿童', '作词：段思思\n作曲：谭旋\n原唱：张靓颖\n翻唱/混音：诺言Jason', '诺言Jason', 0, '正常', '蓝光', '2022-03-14 22:28:24');
INSERT INTO `article` VALUES (1181, '【原创黑暗风歌曲】倒悬 - 鲤音', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/d0d4f665fed539343ea3a047c2b842ff.jpg', '电音,电音,英文', '演唱：鲤音\r\n作词：陆槿夕\r\n作曲：续薪小墨\r\n编曲：斓音音乐工作室\r\n和声：小雪人\r\n题字：揾溺_\r\n海报/PV：一阳\r\n混音：第伍千鲤\r\nDemo：衾颜\r\n（本歌曲不开放任何形式商用授权，仅开放非商业性质纯翻唱授权；翻唱请完整写明原staff人员。）', '鲤音', 0, '正常', '蓝光', '2022-03-14 22:28:24');
