INSERT INTO `article` VALUES (1237, 'ベリーメリークリスマス', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/0138984770404589a0be4ccd5a9b5cca.jpg', '新歌', 'Song by Very Merry Christmas\nCover by 墨逸轩\nメリークリスマス！！！\n圣诞快乐！！！\n这次翻唱了 天月-あまつき- 的 ベリーメリークリスマス，趁着这次圣诞节再一次翻唱了一首有关圣诞的日语歌曲，希望各位喜欢。喜欢的别忘了XXX哟！', '墨逸轩_Asaitsunoki', 0, '正常', '超清', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1238, '九域无疆', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/997a512414d750963eb2e1c4feb874da.jpg', '粤语,情歌,情歌,酒吧,日本', '《九域无疆》\r\n\r\n总策划/制作人：嫦綰、Coco烟岚\r\n作词：苏药卿、马小瞳、烟花瀑布、紫羽映月、良时、七手、上河、素昭、丝齐、紫云纱、安羽、野野、凉盏\r\n作曲：黄诗扶HBY\r\n演唱：小曲儿、HITA、司夏、Smile_小千、Braska、冥月、流浪的蛙蛙\r\n编曲：sea云\r\n和声：嫦绾、冥月、司夏\r\n混音：NamieMeng\r\n海报/pv底图：苍茕\r\n题字：聆泽\r\nPv：缄玫\r\n监策：紫羽映月、安羽\r\n监制：白衣SAMA、妖旋宝\r\n出品：步知名原创组\r\n\r\n', '步知名原创合唱组', 0, '正常', '标清', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1239, '“不辞冰雪为卿热”', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/057e878a63e20ea4aa934a58c22f3cc0.png', '粤语,儿童', '《少年游之一寸相思》\n宝藏剧，很好看。\n\n《涉川》翻唱\n词：怀袖\n曲：少司命\n编曲：灰原穷/纪粹希\n和声：小时姑娘\n和声编写：银临\n原唱：不才\n翻唱：云扶', '云扶', 0, '正常', '超清', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1240, '【诺言Jason】一生一次心一动(《斛珠夫人》电视剧主题曲', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/0df9297939aadfc28738c96043dc7cbf.jpg', '朋克,说唱,治愈,粤语,华语', '作词：段思思\n作曲：谭旋\n原唱：张靓颖\n翻唱/混音：诺言Jason', '诺言Jason', 0, '正常', '蓝光', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1241, '【原创黑暗风歌曲】倒悬 - 鲤音', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/d0d4f665fed539343ea3a047c2b842ff.jpg', '朋克,运动', '演唱：鲤音\r\n作词：陆槿夕\r\n作曲：续薪小墨\r\n编曲：斓音音乐工作室\r\n和声：小雪人\r\n题字：揾溺_\r\n海报/PV：一阳\r\n混音：第伍千鲤\r\nDemo：衾颜\r\n（本歌曲不开放任何形式商用授权，仅开放非商业性质纯翻唱授权；翻唱请完整写明原staff人员。）', '鲤音', 0, '正常', '蓝光', '2022-03-14 22:28:25');
