INSERT INTO `article` VALUES (1265, '我有明堂风雪裁《将进酒》策舟同人歌', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/e2981275c50e413366cdf9bea3554aa2.jpg', '新歌', '我有明堂风雪裁——《将进酒》策舟同人歌\r\n演唱：策安-诺言Jason/兰舟-Babystop_山竹\r\n策划：檀卿卿\r\n作曲：李星月\r\n作词：闻刀客\r\n编曲：洛劫\r\n和声编写：李星月/巫汐\r\n和声演唱：巫汐\r\n修对：临溪\r\n分轨/人声混音：牧子Assyria\r\n歌名题字：聆泽Lains\r\nPV全词：檀卿卿\r\nPV底图：白鹿\r\n美工：竹名君\r\nPV：浔漪Hazy\r\n立绘：胖叽叽叽叽叽/山烟雅坠\r\n授权画师：哮天小狗狗/Kuzpao鱼泡/遥山时人/南风。/霜月', '诺言Jason', 0, '正常', '蓝光', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1266, '子弥 - 喜雨', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/edb20b6229ad46a3b3830ee5529f057c.jpg', '动漫,DJ,欧美,经典,摇滚', '暂无简介', '子弥MiFaFa', 0, '正常', '蓝光', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1267, 'ベリーメリークリスマス', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/0138984770404589a0be4ccd5a9b5cca.jpg', '运动,治愈', 'Song by Very Merry Christmas\nCover by 墨逸轩\nメリークリスマス！！！\n圣诞快乐！！！\n这次翻唱了 天月-あまつき- 的 ベリーメリークリスマス，趁着这次圣诞节再一次翻唱了一首有关圣诞的日语歌曲，希望各位喜欢。喜欢的别忘了XXX哟！', '墨逸轩_Asaitsunoki', 0, '正常', '超清', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1268, '九域无疆', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/997a512414d750963eb2e1c4feb874da.jpg', '旅行,游戏', '《九域无疆》\r\n\r\n总策划/制作人：嫦綰、Coco烟岚\r\n作词：苏药卿、马小瞳、烟花瀑布、紫羽映月、良时、七手、上河、素昭、丝齐、紫云纱、安羽、野野、凉盏\r\n作曲：黄诗扶HBY\r\n演唱：小曲儿、HITA、司夏、Smile_小千、Braska、冥月、流浪的蛙蛙\r\n编曲：sea云\r\n和声：嫦绾、冥月、司夏\r\n混音：NamieMeng\r\n海报/pv底图：苍茕\r\n题字：聆泽\r\nPv：缄玫\r\n监策：紫羽映月、安羽\r\n监制：白衣SAMA、妖旋宝\r\n出品：步知名原创组\r\n\r\n', '步知名原创合唱组', 0, '正常', '标清', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1269, '“不辞冰雪为卿热”', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/057e878a63e20ea4aa934a58c22f3cc0.png', '轻音乐,DJ', '《少年游之一寸相思》\n宝藏剧，很好看。\n\n《涉川》翻唱\n词：怀袖\n曲：少司命\n编曲：灰原穷/纪粹希\n和声：小时姑娘\n和声编写：银临\n原唱：不才\n翻唱：云扶', '云扶', 0, '正常', '超清', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1270, '【诺言Jason】一生一次心一动(《斛珠夫人》电视剧主题曲', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/0df9297939aadfc28738c96043dc7cbf.jpg', '情歌,欧美,台湾,日韩,华语', '作词：段思思\n作曲：谭旋\n原唱：张靓颖\n翻唱/混音：诺言Jason', '诺言Jason', 0, '正常', '蓝光', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1271, '【原创黑暗风歌曲】倒悬 - 鲤音', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/d0d4f665fed539343ea3a047c2b842ff.jpg', '华语,DJ,拉丁', '演唱：鲤音\r\n作词：陆槿夕\r\n作曲：续薪小墨\r\n编曲：斓音音乐工作室\r\n和声：小雪人\r\n题字：揾溺_\r\n海报/PV：一阳\r\n混音：第伍千鲤\r\nDemo：衾颜\r\n（本歌曲不开放任何形式商用授权，仅开放非商业性质纯翻唱授权；翻唱请完整写明原staff人员。）', '鲤音', 0, '正常', '蓝光', '2022-03-14 22:28:25');
