INSERT INTO `article` VALUES (1274, '《凌云诺》手游主题曲《凌云赋》', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/234632d0d5b1534bd8ab250deeaaf216.jpg', '台湾,酒吧,网络红歌', '作为友谊时光强推的年度大型女性古风手游《凌云诺》的主题曲，歌曲中融入了戏腔、rap、古风元素，为听众和玩家带来不一样的古风音乐表现方式，将游戏中女性自强，报效国家，创盛世太平的积极精神传达给大家。', '凌云诺手游', 0, '正常', '蓝光', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1275, '《知否、知否》电视剧（知否、知否，应是绿肥红瘦）主题曲MV', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/c91c3f7356649ad7c9b56ee89d383cb6.jpg', '游戏,华语,儿童', '这部剧当时也是火遍大江南北  留下美好的记忆', '九墨音乐', 0, '正常', '超清', '2022-03-14 22:28:25');
INSERT INTO `article` VALUES (1276, '【诺言Jason】孤勇者', 'http://www.javalm.cn/file/1.mp3', 'https://wsingbssdl.kugou.com/08ce61f9b10c1e75546715e3ef4e38cd.jpg', '金曲,英文,轻音乐,DJ', '不完美的梦，可以不乘风。\n一腔孤勇者，奔赴一个梦。\n从黑暗中生长的信念会成为光，\n与命运对峙过的人，都是勇敢者。\n\n作词：唐恬\n作曲：钱雷\n原唱：陈奕迅\n翻唱/混音：诺言Jason\n剪辑：银灯', '诺言Jason', 0, '正常', '蓝光', '2022-03-14 22:28:25');
